from sympy import factorint

def calculate_a_n(n):
    # Closed form: a_n = 6^n + 2^n + 3^n - 1
    return 6**n + 2**n + 3**n - 1

terms = list(range(7, 13))
results = {}

for n in terms:
    a_n = calculate_a_n(n)
    factors = factorint(a_n)
    results[n] = {'value': a_n, 'factors': factors}

print("--- Calculations ---")
for n, data in results.items():
    value = data['value']
    factors = data['factors']
    print(f"a_{n} = {value}")
    print(f"Prime factorization of a_{n}: {factors}")

all_primes = set()
for n, data in results.items():
    for prime in data['factors']:
        all_primes.add(prime)

print(f"\nNew prime factors found: {all_primes}")

def a_n_mod_p(n, p):
    # a_n = 6^n + 2^n + 3^n - 1
    return (pow(6, n, p) + pow(2, n, p) + pow(3, n, p) - 1) % p

primes = [11, 13, 17, 19]
max_n = 30 # Check up to n=30 to look for patterns

results = {}

for p in primes:
    residues = []
    for n in range(1, max_n + 1):
        r = a_n_mod_p(n, p)
        residues.append(r)
        if r == 0:
            print(f"Prime {p} divides a_{n}.")

    results[p] = residues

print("\n--- Results Summary ---")
for p in primes:
    print(f"Residues mod {p} (first {max_n} terms): {results[p]}")
